def localize(value, lang):
    if isinstance(value, bool):
        return {'zh': ('否','是'), 'en': ('No','Yes'), 'ja': ('いいえ','はい'), 'es': ('No','Sí')}[lang][value]
    if value is None:
        return '—'
    if lang == 'zh' or value not in FIELDS:
        return value
    return FIELDS[value][{'en':0,'ja':1,'es':2}[lang]]
